CREATE TEMPORARY VIEW cheapest_model_list_${grass_region_without_quote} AS
select cspu_id
    ,model_id
    ,item_id
    ,coalesce(b.type,'non-scs') as shop_scs_type
    ,business_type
    ,local_hour
from srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf a
left join (
    select type
         ,shop_id
    from regds_listing.dim_scs_shop_list_df
    where grass_region = ${grass_region}
      and type in ('scs-local','scs-cb')
)b
on a.shop_id = b.shop_id
where grass_region = ${grass_region} AND local_date = ${local_date}
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW cheapest_item_list_${grass_region_without_quote} AS
select item_id
     ,local_hour
from cheapest_model_list_${grass_region_without_quote}
group by item_id, local_hour
;
