CREATE TEMPORARY VIEW cspu_model_level_${grass_region_without_quote} AS
select cspu_id
    ,if(grouping(is_item_card)=1,'__ALL__',is_item_card) as is_item_card
    ,mapping_general
    ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
    ,sum(order_cnt) cspu_model_order_cnt
from (select cspu_id
        ,is_item_card
        ,mapping_general
        ,is_ads
        ,sum(order_cnt) order_cnt
      from cspu_model_level_step1_${grass_region_without_quote}
