          from cspu_model_level_step1_${grass_region_without_quote} a
        inner join cheapest_model_list_${grass_region_without_quote} b
        on a.local_hour = b.local_hour
        and a.model_id = b.model_id
        where b.business_type in (2,3,4)
        group by 1,2,3,4,5,6,7,8,9)x
group by model_id
