CREATE TEMPORARY VIEW item_level_${grass_region_without_quote} AS
SELECT item_id
     ,if(grouping(is_item_card)=1,'__ALL__',is_item_card) as is_item_card
     ,mapping_general
     ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
     ,sum(imp_cnt) item_imp_pv
     ,count(distinct if(imp_cnt>0,user_id,null)) item_imp_uv
     ,sum(order_cnt) item_order_cnt
     ,count(distinct if(order_cnt>0,user_id,null)) item_order_uv
     ,sum(gmv) item_gmv
     ,sum(gmv_local) item_gmv_local
from (SELECT item_id
        ,is_item_card
        ,mapping_general
        ,is_ads
        ,user_id
        ,sum(imp_cnt)   imp_cnt
        ,sum(order_cnt) order_cnt
        ,sum(gmv)       gmv
        ,sum(gmv_local) gmv_local
      FROM (SELECT a.local_hour
                 , a.item_id
                 , is_item_card
                 , mapping_general
                 , is_ads
                 , user_id
                 , MAX(imp_cnt)   imp_cnt
                 , MAX(order_cnt) order_cnt
                 , MAX(gmv)       gmv
                 , MAX(gmv_local) gmv_local
            FROM cspu_item_level_step1_${grass_region_without_quote} a
            INNER JOIN cheapest_item_list_${grass_region_without_quote} b
            ON a.local_hour = b.local_hour
            AND a.item_id = b.item_id
