      )y
group by item_id
       ,is_item_card
       ,mapping_general
       ,is_ads
    GROUPING SETS (
    (item_id,is_item_card,mapping_general,is_ads),
    (item_id,mapping_general,is_ads),
    (item_id,is_item_card,mapping_general),
    (item_id,mapping_general)
    )
;
