CREATE TEMPORARY VIEW scene_data_${grass_region_without_quote} AS
select  if(grouping(is_item_card)=1,'__ALL__',is_item_card) as is_item_card
     ,mapping_general
     ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
     ,sum(imp_cnt) scene_item_imp_pv
     ,count(distinct if(imp_cnt>0,user_id,null)) scene_item_imp_uv
     ,sum(order_cnt) scene_order_cnt
     ,count(distinct if(order_cnt>0,user_id,null)) scene_order_uv
     ,sum(gmv) scene_gmv
     ,sum(gmv_local) scene_gmv_local
from (SELECT is_item_card
           , mapping_general
           , is_ads
           , user_id
           , SUM(imp_cnt)   imp_cnt
           , SUM(order_cnt) order_cnt
           , SUM(gmv)       gmv
           , SUM(gmv_local) gmv_local
      FROM traffic_data_${grass_region_without_quote}
      GROUP BY 1, 2, 3, 4)x
group by is_item_card
    ,mapping_general
    ,is_ads
    grouping sets(
