CREATE TEMPORARY VIEW ads_raw_step1_${grass_region_without_quote} as
select
    item_id
     ,ads_revenue_local
     ,ads_revenue_usd
     ,coalesce(T2.traffic_type, 'Other') as common_feature
from
    (
        select
            item_id
             ,expenditure_amt_local as ads_revenue_local
             ,expenditure_amt_usd as ads_revenue_usd
             ,entrance
        from mp_paidads.dwd_advertise_performance_di__reg_s0_live
        where grass_region in (${grass_region}) and grass_date=${local_date} and tz_type='local'
    ) as T1
        left join (
        select
            entrance
             ,max(traffic_type) as traffic_type
        from mp_paidads.dim_entry_point_mapping_v2
        group by 1
    ) as T2 on T1.entrance = T2.entrance
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_raw_step2_${grass_region_without_quote} AS
select
    item_id
     ,common_feature
     ,sum(ads_revenue_local) as ads_revenue_local
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step1_${grass_region_without_quote}
group by
    item_id
    ,common_feature
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_${grass_region_without_quote} as
select
    item_id
     ,common_feature
     ,ads_revenue_local
     ,ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','You May Also Like','Daily Discover','Post Purchase','Shop')
union all
select
    item_id
     ,'S&R__ALL__' as common_feature
     ,sum(ads_revenue_local) as ads_revenue_local
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','You May Also Like','Daily Discover','Post Purchase')
group by
    item_id
union all
select
    item_id
     ,'__ALL__' as common_feature
     ,sum(ads_revenue_local) as ads_revenue_local
     ,sum(ads_revenue_usd) as ads_revenue_usd
from ads_raw_step2_${grass_region_without_quote}
group by
    item_id
;
--sql_divide_splitter--
INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_one_variation_scene_overall_1d partition (grass_region = ${grass_region},local_date = ${local_date})
SELECT a.model_id
    ,a.item_id
    ,a.is_item_card
    ,a.mapping_general
    ,a.is_ads
    ,a.shop_scs_type
    ,a.business_type
    ,item_imp_pv
    ,item_imp_uv
    ,item_order_cnt
    ,item_order_uv
    ,item_gmv
    ,item_gmv_local
    ,model_order_cnt
    ,model_order_uv
    ,model_gmv
    ,model_gmv_local
    ,ads_revenue_local
    ,ads_revenue_usd
    ,cspu_item_imp_pv
    ,cspu_item_order_cnt
    ,cspu_model_order_cnt
    ,scene_item_imp_pv
    ,scene_item_imp_uv
    ,scene_order_cnt
    ,scene_order_uv
    ,scene_gmv
    ,scene_gmv_local
from model_level_${grass_region_without_quote} a
left join item_level_${grass_region_without_quote} b
on a.is_item_card = b.is_item_card and a.mapping_general = b.mapping_general and a.is_ads = b.is_ads and a.item_id = b.item_id
left join cspu_model_level_${grass_region_without_quote} c
on a.is_item_card = c.is_item_card and a.mapping_general = c.mapping_general and a.is_ads = c.is_ads and a.cspu_id = c.cspu_id
left join cspu_item_level_${grass_region_without_quote} d
on a.is_item_card = d.is_item_card and a.mapping_general = d.mapping_general and a.is_ads = d.is_ads and a.cspu_id = d.cspu_id
left join ads_${grass_region_without_quote} e
on a.item_id = e.item_id and a.mapping_general = e.common_feature and a.is_item_card == '__ALL__' and a.is_ads = '__ALL__'
left join scene_data_${grass_region_without_quote} f
on a.is_item_card = f.is_item_card and a.mapping_general = f.mapping_general and a.is_ads = f.is_ads
;

